import type { Db } from "mongodb";
import { ensureIndex } from "./helpers";

/**
 * Indexes for the crises collection:
 *
 *   - `status + autoGenerated` — the per-turn auto-disaster query filters on
 *     both fields: `crises.find({ status: "active", autoGenerated: true })`.
 */
export async function seedCrisisIndexes(db: Db, log: (msg: string) => void) {
  log("Crisis indexes:");

  await ensureIndex(
    db,
    "crises",
    { status: 1, autoGenerated: 1 },
    { name: "crises_status_autoGenerated" },
    log
  );

  log("Crisis indexes ensured");
}
